CREATE TABLE harvests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, crop_id BIGINT UNSIGNED NOT NULL, financial_transaction_id BIGINT UNSIGNED NULL, harvest_date DATE NOT NULL, quantity DECIMAL(15,2) NOT NULL, unit VARCHAR(30) NOT NULL, quality_grade VARCHAR(50) NULL, revenue_amount DECIMAL(15,2) NOT NULL DEFAULT 0.00, buyer_name VARCHAR(200) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_harvests_ft (financial_transaction_id), KEY idx_harvests_crop_date (crop_id,harvest_date), CONSTRAINT chk_harvests_values CHECK (quantity > 0 AND revenue_amount >= 0), CONSTRAINT fk_harvests_crop FOREIGN KEY (crop_id) REFERENCES crops(id) ON DELETE RESTRICT, CONSTRAINT fk_harvests_ft FOREIGN KEY (financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
